    public static void Write(string file,DraftReport report)
    {
        var reasons=report.Runs.SelectMany(r=>r.Samples.Select(s=>s.Reason)).Distinct().ToArray();
        double R(double x)=>Math.Round(x,5);
        var playback=report.Runs.Where(r=>r.Seed==1).Select(r=>new{
            r.Name,r.Passive,r.Setup,
            frames=r.Samples.Where((s,i)=>i%2==0||i==r.Samples.Count-1).Select(s=>new[]{s.T,s.E,s.N,s.H,s.Beta,s.ToolE,s.ToolN,s.Error,s.Offset,s.Steer,s.Slope,s.SoilForce,s.DraftForce,s.GravityForce,s.GripUsage,s.Speed,s.Engaged?1d:0,s.MeasuredE,s.MeasuredN,s.HitchE,s.HitchN,(double)Array.IndexOf(reasons,s.Reason)}.Select(R).ToArray()).ToArray()
        });
        var data=JsonSerializer.Serialize(new {report,playback,reasons,paths=report.Runs.Where(r=>r.Seed==1&&r.Passive).Select(r=>new{r.Name,points=DraftSuite.ReferencePath(r.Setup).Select(p=>new[]{R(p.Easting),R(p.Northing)})})},new JsonSerializerOptions{PropertyNamingPolicy=JsonNamingPolicy.CamelCase});
        File.WriteAllText(file,"""
