<h1>Implement draft: straight and curve simulation</h1><p id="summary"></p><p id="model"></p>
<section><h2>Watch the implement pull sideways</h2><div class="controls"><select id="case" aria-label="Scenario"></select><button id="play">Play</button><button id="restart">Restart</button><label>Speed <select id="rate"><option>1</option><option selected>5</option><option>10</option><option>20</option></select>×</label><label><input id="follow" type="checkbox" checked>Follow rig</label><label>View <select id="span"><option>40</option><option selected>70</option><option>120</option><option>250</option></select> m</label></div><p><input id="time" type="range" min="0" max="180" value="0" step="0.1" aria-label="Replay time"> <span id="clock"></span></p>
