arrow([p[5],p[6]],p[12],'#d74e49');arrow(axle,p[13],'#9054bd');arrow(axle,p[11],'#259d76');if(p[16]){ctx.fillStyle='#17becf';ctx.beginPath();ctx.arc(X(p[17]),Y(p[18]),4,0,Math.PI*2);ctx.fill()}
